INSERT INTO public.cbt_questions (id, type, subject, text, media_type, media_url, options, pairs, answer, weight, explanation) VALUES
  ('Q_20261101_08_11', 'PG', 'IPA SMP 8', 'Upaya menekan emisi gas rumah kaca tidak hanya berfokus pada sektor industri dan transportasi, tetapi juga sektor pertanian dan peternakan. Pengelolaan limbah kotoran ternak sapi yang menumpuk tanpa diolah dapat memperparah efek rumah kaca karena proses penguraian anaerobik menghasilkan gas ....', 'none', '', '["karbon monoksida (CO) yang merusak lapisan stratosfer", "klorofluorokarbon (CFC) yang memerangkap panas di atmosfer", "metana (CH₄) yang memiliki daya ikat panas jauh lebih kuat daripada CO₂", "sulfur dioksida (SO₂) yang memicu terjadinya hujan asam"]'::jsonb, '[]'::jsonb, 'klorofluorokarbon (CFC) yang memerangkap panas di atmosfer', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_12', 'PG', 'IPA SMP 8', 'Pemanasan global menyebabkan mencairnya lapisan es daratan di Greenland dan Antarktika dalam volume besar. Selain menaikkan permukaan air laut, masuknya air tawar dalam jumlah masif ke samudra dapat mengganggu keseimbangan iklim global karena ....', 'none', '', '["meningkatkan kadar garam (salinitas) air laut sehingga memicu penguapan ekstrem", "menurunkan salinitas air laut sehingga menghambat sirkulasi arus laut global (thermohaline)", "mempercepat pembekuan air laut di sekitar garis khatulistiwa pada malam hari", "mengurangi kemampuan lautan dalam memantulkan radiasi panas Matahari ke angkasa"]'::jsonb, '[]'::jsonb, 'menurunkan salinitas air laut sehingga menghambat sirkulasi arus laut global (thermohaline)', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_13', 'PG', 'IPA SMP 8', 'Kota-kota besar di Indonesia mengalami peningkatan suhu udara perkotaan (urban heat island) dan polusi udara akibat tingginya penggunaan kendaraan bermotor pribadi. Strategi mitigasi paling efektif untuk menurunkan emisi karbon di sektor transportasi perkotaan adalah ....', 'none', '', '["mewajibkan penggunaan pendingin udara (AC) ramah lingkungan di setiap mobil pribadi", "memperlebar seluruh jalan raya agar kendaraan pribadi dapat melaju tanpa kemacetan", "mengganti bahan bakar bensin beroktan rendah menjadi bensin beroktan tinggi pada semua kendaraan", "mengembangkan sistem transportasi massal terintegrasi berbasis energi listrik dan jalur pedestrian"]'::jsonb, '[]'::jsonb, 'memperlebar seluruh jalan raya agar kendaraan pribadi dapat melaju tanpa kemacetan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_14', 'PG', 'IPA SMP 8', 'Penggunaan senyawa Klorofluorokarbon (CFC) pada lemari es dan pendingin ruangan lawas telah dilarang secara internasional melalui Protokol Montreal. Dampak utama pelepasan senyawa CFC ke lapisan stratosfer adalah ....', 'none', '', '["bereaksi dengan molekul ozon (O₃) sehingga mengurangi kemampuan atmosfer menyerap sinar ultraviolet", "menghalangi pantulan sinar inframerah dari Bumi sehingga suhu troposfer turun drastis", "meningkatkan kadar oksigen di lapisan termosfer yang memicu badai geomagnetik", "membentuk awan tebal di stratosfer yang menghalangi cahaya tampak Matahari ke Bumi"]'::jsonb, '[]'::jsonb, 'menghalangi pantulan sinar inframerah dari Bumi sehingga suhu troposfer turun drastis', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_15', 'PG', 'IPA SMP 8', 'Seorang siswa di Kota Pontianak yang dilalui garis khatulistiwa melakukan pengamatan panjang bayangan tiang bendera tepat pada pukul 12.00 waktu setempat di tanggal-tanggal tertentu. Pada tanggal 21 Maret dan 23 September, tiang bendera tersebut hampir tidak memiliki bayangan karena ....', 'none', '', '["jarak antara Bumi dan Matahari berada pada titik terjauh (aphelion)", "Matahari tepat berada di garis balik utara (23,5° LU)", "posisi Matahari tepat berada di atas garis ekuator (khatulistiwa)", "kemiringan sumbu rotasi Bumi sedang berada pada sudut 0°"]'::jsonb, '[]'::jsonb, 'Matahari tepat berada di garis balik utara (23,5° LU)', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_16', 'PG', 'IPA SMP 8', 'Perhatikan data anomali suhu permukaan laut (SPL) di Samudra Pasifik bagian tengah dan timur berikut ini!<br>• Tahun X: Anomali SPL sebesar +2,1°C (lebih hangat dari rata-rata normal).<br>• Tahun Y: Anomali SPL sebesar -1,8°C (lebih dingin dari rata-rata normal).<br>Berdasarkan data tersebut, dampak fenomena iklim yang paling tepat terjadi di sebagian besar wilayah Indonesia pada Tahun X beserta langkah adaptasi bagi petani adalah ....', 'none', '', '["Terjadi fenomena La Niña yang memicu curah hujan ekstrem; petani disarankan membuat saluran drainase dan menanam padi tahan rendaman.", "Terjadi fenomena El Niño yang memicu kemarau panjang dan kekeringan; petani disarankan beralih sementara ke tanaman palawija yang hemat air.", "Terjadi fenomena El Niño yang meningkatkan potensi banjir bandang; petani disarankan mempercepat masa panen sebelum puncak musim hujan.", "Terjadi fenomena La Niña yang menyebabkan gagal panen akibat kekeringan; petani disarankan membangun embung penampung air hujan."]'::jsonb, '[]'::jsonb, 'Terjadi fenomena El Niño yang memicu kemarau panjang dan kekeringan; petani disarankan beralih sementara ke tanaman palawija yang hemat air.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_17', 'PG', 'IPA SMP 8', 'Perhatikan ringkasan data pengamatan atmosfer dari stasiun pemantau global (Mauna Loa) berikut ini:<br>• Tahun 1980: Konsentrasi CO₂ = 338 ppm | Anomali Suhu Global = +0,26°C<br>• Tahun 2000: Konsentrasi CO₂ = 369 ppm | Anomali Suhu Global = +0,40°C<br>• Tahun 2020: Konsentrasi CO₂ = 414 ppm | Anomali Suhu Global = +1,02°C<br>Kesimpulan yang paling tepat berdasarkan analisis hubungan kedua variabel dalam data tersebut adalah ....', 'none', '', '["Kenaikan suhu global berbanding terbalik dengan konsentrasi gas karbon dioksida di atmosfer.", "Peningkatan konsentrasi CO₂ sebesar 31 ppm selalu menyebabkan kenaikan suhu tepat sebesar 0,14°C.", "Laju kenaikan anomali suhu global melambat setelah konsentrasi karbon dioksida melampaui 400 ppm.", "Peningkatan konsentrasi CO₂ berkorelasi positif dengan kenaikan anomali suhu global, dengan lonjakan suhu yang semakin tajam pada dua dekade terakhir."]'::jsonb, '[]'::jsonb, 'Peningkatan konsentrasi CO₂ sebesar 31 ppm selalu menyebabkan kenaikan suhu tepat sebesar 0,14°C.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_18', 'PG', 'IPA SMP 8', 'Fase bulan baru dan bulan purnama terjadi setiap sekitar 29,5 hari sekali. Namun, gerhana matahari maupun gerhana bulan tidak terjadi setiap bulan. Penyebab astronomis yang paling akurat untuk menjelaskan fenomena tersebut adalah ....', 'none', '', '["bidang orbit Bulan mengelilingi Bumi membentuk sudut kemiringan sekitar 5° terhadap bidang ekliptika sehingga bayangan Bulan sering meleset dari Bumi", "ukuran diameter Bulan terlalu kecil dibandingkan diameter Bumi sehingga bayangan umbra Bulan jarang mencapai permukaan Bumi", "kecepatan revolusi Bulan berubah-ubah secara drastis setiap bulan akibat pengaruh gaya tarik planet Jupiter", "sumbu rotasi Bumi yang miring 23,5° menyebabkan posisi Bumi selalu bergeser menjauhi garis lurus Matahari–Bulan"]'::jsonb, '[]'::jsonb, 'ukuran diameter Bulan terlalu kecil dibandingkan diameter Bumi sehingga bayangan umbra Bulan jarang mencapai permukaan Bumi', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_19', 'PG', 'IPA SMP 8', 'Pemerintah daerah di sebuah pulau kecil yang memiliki paparan sinar matahari sepanjang tahun dan hembusan angin laut yang stabil berencana mengganti pembangkit listrik tenaga diesel (PLTD) berbahan bakar solar untuk menekan emisi karbon. Evaluasi kebijakan transisi energi yang paling tepat untuk kondisi geografis wilayah tersebut adalah ....', 'none', '', '["Membangun Pembangkit Listrik Tenaga Uap (PLTU) berbahan bakar batu bara karena biaya operasionalnya paling murah bagi pulau kecil.", "Mempertahankan PLTD namun mengganti solar dengan biosolar campuran 10% karena tidak memerlukan investasi infrastruktur baru.", "Membangun sistem pembangkit listrik hibrida tenaga surya (PLTS) dan tenaga bayu (PLTB) yang dilengkapi baterai penyimpanan energi.", "Mengimpor listrik menggunakan kabel bawah laut sepanjang ratusan kilometer dari pulau utama yang masih menggunakan pembangkit berbahan bakar fosil."]'::jsonb, '[]'::jsonb, 'Mempertahankan PLTD namun mengganti solar dengan biosolar campuran 10% karena tidak memerlukan investasi infrastruktur baru.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_20', 'PG', 'IPA SMP 8', 'Pemutihan terumbu karang (coral bleaching) semakin sering dilaporkan terjadi di perairan tropis Indonesia. Peristiwa ini terjadi ketika hewan karang mengeluarkan alga simbiotik (zooxanthellae) dari jaringannya hingga karang tampak memutih dan rentan mati. Keterkaitan antara perubahan iklim global dengan fenomena ini adalah ....', 'none', '', '["Penurunan suhu air laut akibat mencairnya es kutub membunuh alga simbiotik yang hidup di dalam jaringan terumbu karang.", "Peningkatan suhu permukaan laut dan pengasaman laut akibat penyerapan CO₂ berlebih memicu stres fisiologis pada karang sehingga melepaskan zooxanthellae.", "Meningkatnya radiasi sinar ultraviolet akibat penipisan ozon mempercepat fotosintesis zooxanthellae hingga merusak struktur kapur karang.", "Kenaikan permukaan air laut menghalangi cahaya Matahari menembus dasar laut sehingga karang kekurangan nutrisi dari udara."]'::jsonb, '[]'::jsonb, 'Peningkatan suhu permukaan laut dan pengasaman laut akibat penyerapan CO₂ berlebih memicu stres fisiologis pada karang sehingga melepaskan zooxanthellae.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_21', 'PG', 'IPA SMP 8', 'Dalam kajian biologi, tubuh makhluk hidup multiseluler tersusun atas tingkatan struktur dari unit terkecil hingga membentuk individu utuh. Urutan hierarki organisasi kehidupan yang tepat adalah ....', 'none', '', '["Sel → Organ → Jaringan → Sistem Organ → Organisme", "Jaringan → Sel → Organ → Sistem Organ → Organisme", "Sel → Jaringan → Organ → Sistem Organ → Organisme", "Sel → Jaringan → Sistem Organ → Organ → Organisme"]'::jsonb, '[]'::jsonb, 'Jaringan → Sel → Organ → Sistem Organ → Organisme', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_22', 'PG', 'IPA SMP 8', 'Sel otot jantung dan sel hati memiliki jumlah organel tertentu yang jauh lebih banyak dibandingkan sel lemak karena kedua sel tersebut membutuhkan energi dalam jumlah besar secara terus-menerus. Organel sel yang berfungsi sebagai tempat berlangsungnya respirasi seluler untuk menghasilkan energi (ATP) adalah ....', 'none', '', '["Mitokondria", "Ribosom", "Badan Golgi", "Lisosom"]'::jsonb, '[]'::jsonb, 'Ribosom', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_23', 'PG', 'IPA SMP 8', 'Ketika mengamati preparat sel epitel pipi manusia dan sel daun Hydrilla di bawah mikroskop cahaya, struktur yang hanya ditemukan pada sel daun Hydrilla tetapi tidak dimiliki oleh sel epitel pipi adalah ....', 'none', '', '["membran sel dan sitoplasma", "inti sel (nukleus) dan mitokondria", "ribosom dan retikulum endoplasma", "dinding sel dan kloroplas"]'::jsonb, '[]'::jsonb, 'inti sel (nukleus) dan mitokondria', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_24', 'PG', 'IPA SMP 8', 'Makanan yang masuk ke dalam lambung akan mengalami pencernaan secara mekanis oleh otot dinding lambung serta pencernaan secara kimiawi dengan bantuan getah lambung. Enzim yang dihasilkan oleh kelenjar di dinding lambung beserta fungsinya yang tepat adalah ....', 'none', '', '["Amilase, mengubah amilum menjadi maltosa", "Pepsin, memecah protein menjadi pepton", "Lipase, mengemulsikan lemak menjadi asam lemak", "Tripsin, mengubah pepton menjadi asam amino"]'::jsonb, '[]'::jsonb, 'Pepsin, memecah protein menjadi pepton', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_25', 'PG', 'IPA SMP 8', 'Proses metabolisme di dalam sel-sel tubuh menghasilkan zat sisa yang bersifat racun jika menumpuk. Organ ekskresi yang berfungsi menyaring darah untuk membuang sisa metabolisme berupa urea, kelebihan air, dan garam mineral dalam bentuk urine adalah ....', 'none', '', '["Hati", "Paru-paru", "Ginjal", "Kulit"]'::jsonb, '[]'::jsonb, 'Paru-paru', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_26', 'PG', 'IPA SMP 8', 'Alveolus pada paru-paru tersusun atas jaringan epitel pipih selapis yang sangat tipis serta dikelilingi oleh jaringan pembuluh darah kapiler yang rapat. Keterkaitan antara struktur jaringan penyusun alveolus tersebut dengan fungsinya adalah ....', 'none', '', '["memperpendek jarak difusi sehingga pertukaran gas oksigen dan karbon dioksida berlangsung cepat dan efisien", "menahan tekanan udara yang sangat tinggi saat seseorang menahan napas dalam waktu lama", "menghasilkan lendir dalam jumlah banyak untuk menyaring debu dan bakteri yang masuk bersama udara", "memperkuat struktur paru-paru agar tidak mengempis saat fase ekspirasi berlangsung"]'::jsonb, '[]'::jsonb, 'menahan tekanan udara yang sangat tinggi saat seseorang menahan napas dalam waktu lama', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_27', 'PG', 'IPA SMP 8', 'Sistem peredaran darah manusia merupakan sistem peredaran darah ganda yang terdiri atas peredaran darah kecil dan peredaran darah besar. Urutan aliran darah pada sistem peredaran darah kecil yang benar adalah ....', 'none', '', '["Bilik kiri → Aorta → Seluruh tubuh → Vena kava → Serambi kanan", "Bilik kanan → Vena pulmonalis → Paru-paru → Arteri pulmonalis → Serambi kiri", "Serambi kanan → Bilik kanan → Aorta → Paru-paru → Serambi kiri", "Bilik kanan → Arteri pulmonalis → Paru-paru → Vena pulmonalis → Serambi kiri"]'::jsonb, '[]'::jsonb, 'Bilik kanan → Vena pulmonalis → Paru-paru → Arteri pulmonalis → Serambi kiri', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_28', 'PG', 'IPA SMP 8', 'Saat seseorang menarik napas dalam-dalam menggunakan mekanisme pernapasan dada, terjadi serangkaian perubahan pada otot dan rongga dada. Mekanisme fase inspirasi pada pernapasan dada yang tepat adalah ....', 'none', '', '["otot antartulang rusuk relaksasi → tulang rusuk turun → volume rongga dada mengecil → udara masuk", "otot antartulang rusuk berkontraksi → tulang rusuk terangkat → volume rongga dada membesar → tekanan udara paru-paru mengecil → udara masuk", "otot diafragma berkontraksi → diafragma mendatar → tekanan udara rongga dada membesar → udara masuk", "otot antartulang rusuk berkontraksi → tulang rusuk turun → tekanan udara paru-paru membesar → udara keluar"]'::jsonb, '[]'::jsonb, 'otot antartulang rusuk berkontraksi → tulang rusuk terangkat → volume rongga dada membesar → tekanan udara paru-paru mengecil → udara masuk', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_29', 'PG', 'IPA SMP 8', 'Seorang siswa mengonsumsi suplemen vitamin C dosis tinggi melebihi kebutuhan harian tubuhnya. Kelebihan vitamin yang larut dalam air tersebut akan dibuang bersama urine melalui tahapan pembentukan urine di nefron ginjal, khususnya pada tahap augmentasi. Proses yang terjadi pada tahap augmentasi di tubulus kontortus distal adalah ....', 'none', '', '["penyaringan sel-sel darah dan protein berukuran besar dari glomerulus ke kapsula Bowman", "penyerapan kembali seluruh glukosa dan asam amino yang masih dibutuhkan tubuh ke pembuluh darah", "penambahan zat-zat sisa yang tidak dibutuhkan tubuh seperti ion hidrogen (H⁺), kalium (K⁺), dan sisa obat/vitamin ke dalam urine sekunder", "penampungan sementara urine sesungguhnya sebelum dialirkan menuju ureter dan kandung kemih"]'::jsonb, '[]'::jsonb, 'penyerapan kembali seluruh glukosa dan asam amino yang masih dibutuhkan tubuh ke pembuluh darah', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_30', 'PG', 'IPA SMP 8', 'Remaja yang gemar mengonsumsi makanan cepat saji (fast food), jarang makan sayur dan buah, serta kurang minum air putih sering mengalami gangguan pencernaan berupa feses yang keras dan sulit dikeluarkan (sembelit/konstipasi). Gangguan ini terjadi karena ....', 'none', '', '["kurangnya serat makanan menyebabkan gerakan peristaltik usus besar melambat sehingga penyerapan air dari sisa makanan terjadi secara berlebihan", "dinding lambung memproduksi asam klorida (HCl) secara berlebihan sehingga merusak lapisan mukosa usus halus", "infeksi bakteri pada usus besar menghambat penyerapan air sehingga sisa makanan menjadi terlalu padat", "kelenjar pankreas gagal menghasilkan enzim amilase dan lipase untuk mencerna karbohidrat serta lemak"]'::jsonb, '[]'::jsonb, 'dinding lambung memproduksi asam klorida (HCl) secara berlebihan sehingga merusak lapisan mukosa usus halus', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_31', 'PG', 'IPA SMP 8', 'Perhatikan karakteristik dua jenis pembuluh darah berikut ini:<br>• Pembuluh X: Dinding tebal dan elastis, letak agak tersembunyi di dalam, denyut terasa kuat, memiliki satu katup di pangkal jantung.<br>• Pembuluh Y: Dinding tipis dan kurang elastis, letak dekat permukaan kulit, denyut tidak terasa, memiliki banyak katup di sepanjang pembuluh.<br>Berdasarkan karakteristik tersebut, fungsi yang tepat untuk Pembuluh Y adalah ....', 'none', '', '["mengalirkan darah kaya oksigen keluar dari bilik kiri jantung menuju seluruh jaringan tubuh", "mengalirkan darah bertekanan sangat tinggi dari jantung menuju kapiler di seluruh organ", "mengalirkan darah kaya oksigen dari bilik kanan jantung menuju paru-paru untuk pertukaran gas", "mengalirkan darah kembali menuju serambi jantung dengan bantuan kontraksi otot rangka dan katup pencegah aliran balik"]'::jsonb, '[]'::jsonb, 'mengalirkan darah bertekanan sangat tinggi dari jantung menuju kapiler di seluruh organ', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_32', 'PG', 'IPA SMP 8', 'Pada batang tumbuhan dikotil, terdapat jaringan pembuluh yang tersusun dalam berkas pengangkut. Apabila kulit batang tumbuhan dikotil dikelupas melingkar hingga menghilangkan jaringan floemnya, bagian atas sayatan akan membengkak setelah beberapa minggu karena ....', 'none', '', '["pengangkutan air dan garam mineral dari akar menuju daun terhenti total", "hasil fotosintesis dari daun tidak dapat diedarkan menuju bagian akar sehingga menumpuk di bagian atas sayatan", "jaringan xilem mengalami pertumbuhan sekunder yang tidak terkendali di bagian atas luka", "proses transpirasi pada daun meningkat drastis akibat terputusnya aliran hormon dari akar"]'::jsonb, '[]'::jsonb, 'hasil fotosintesis dari daun tidak dapat diedarkan menuju bagian akar sehingga menumpuk di bagian atas sayatan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_33', 'PG', 'IPA SMP 8', 'Penyakit batu ginjal ditandai dengan nyeri hebat pada pinggang bagian bawah dan kesulitan buang air kecil. Secara fisiologis, terbentuknya endapan kristal keras di dalam rongga ginjal atau saluran kemih paling sering dipicu oleh ....', 'none', '', '["infeksi virus yang menyerang glomerulus sehingga sel darah merah lolos ke dalam urine", "kerusakan sel beta pankreas yang menyebabkan kadar glukosa dalam darah meningkat drastis", "kebiasaan kurang minum air putih disertai konsumsi makanan tinggi kalsium, oksalat, atau asam urat yang memicu kristalisasi garam mineral", "penyumbatan saluran empedu oleh kolesterol sehingga zat warna empedu masuk ke peredaran darah"]'::jsonb, '[]'::jsonb, 'kerusakan sel beta pankreas yang menyebabkan kadar glukosa dalam darah meningkat drastis', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_34', 'PG', 'IPA SMP 8', 'Perokok aktif maupun perokok pasif yang terpapar asap rokok dalam jangka panjang sangat rentan mengalami bronkitis kronis dan infeksi saluran pernapasan berulang. Hal ini disebabkan oleh kandungan tar dan zat kimia berbahaya dalam asap rokok yang mengakibatkan ....', 'none', '', '["kelumpuhan dan kerusakan silia pada epitel trakea serta bronkus sehingga lendir dan debu gagal disapu keluar", "pelebaran alveoli secara permanen sehingga kapasitas total paru-paru meningkat melebihi batas normal", "peningkatan jumlah sel darah merah secara drastis yang menyumbat pembuluh kapiler di sekitar alveolus", "pengikatan gas oksigen secara permanen oleh hemoglobin sehingga jaringan tubuh kekurangan karbon dioksida"]'::jsonb, '[]'::jsonb, 'pelebaran alveoli secara permanen sehingga kapasitas total paru-paru meningkat melebihi batas normal', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_35', 'PG', 'IPA SMP 8', 'Hati merupakan kelenjar terbesar di dalam tubuh manusia yang berperan dalam sistem pencernaan sekaligus sistem ekskresi. Peran utama hati dalam membantu proses pencernaan makanan di usus dua belas jari (duodenum) adalah ....', 'none', '', '["menghasilkan enzim lipase untuk memecah lemak secara kimiawi menjadi asam lemak dan gliserol", "menetralkan asam lambung menggunakan senyawa natrium bikarbonat sebelum makanan masuk ke usus halus", "menyerap sari-sari makanan berupa glukosa dan asam amino untuk diedarkan ke seluruh tubuh", "menghasilkan cairan empedu yang mengandung garam empedu untuk mengemulsikan lemak menjadi butiran-butiran halus"]'::jsonb, '[]'::jsonb, 'menetralkan asam lambung menggunakan senyawa natrium bikarbonat sebelum makanan masuk ke usus halus', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_36', 'PG', 'IPA SMP 8', 'Perhatikan data hasil pemeriksaan laboratorium sampel urine dari dua orang pasien berikut ini!<br><table style="border-collapse:collapse; width:100%; margin:8px 0; font-size:0.88rem;"><tr><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Komponen Uji</th><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Nilai Normal</th><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Pasien A</th><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Pasien B</th></tr><tr><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Protein (Albumin)</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Negatif (-)</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Positif (++)</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Negatif (-)</td></tr><tr><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Glukosa</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Negatif (-)</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Negatif (-)</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Positif (+++)</td></tr><tr><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Warna Urine</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Kuning jernih</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Kuning keruh</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Kuning jernih</td></tr></table><br>Berdasarkan hasil uji laboratorium tersebut, analisis kelainan struktur nefron dan diagnosis yang paling tepat adalah ....', 'none', '', '["Pasien A mengalami kerusakan pada tubulus kontortus proksimal sehingga gagal menyerap kembali protein; Pasien B mengalami infeksi pada kandung kemih.", "Pasien A mengalami kerusakan pada glomerulus (albuminuria) sehingga protein lolos saat filtrasi; Pasien B mengalami gangguan reabsorpsi glukosa atau diabetes melitus.", "Pasien A mengalami kelebihan hormon insulin dalam darah; Pasien B mengalami kerusakan pada lengkung Henle sehingga gagal menyerap air.", "Pasien A dan Pasien B sama-sama mengalami penyumbatan pada ureter akibat endapan batu kalsium oksalat."]'::jsonb, '[]'::jsonb, 'Pasien A mengalami kerusakan pada glomerulus (albuminuria) sehingga protein lolos saat filtrasi; Pasien B mengalami gangguan reabsorpsi glukosa atau diabetes melitus.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_37', 'PG', 'IPA SMP 8', 'Seorang pekerja kantoran berusia 40 tahun memiliki kebiasaan mengonsumsi makanan tinggi lemak jenuh dan kolesterol, merokok, serta jarang berolahraga. Hasil pemeriksaan medis menunjukkan adanya penumpukan plak lemak pada dinding dalam arteri koroner (aterosklerosis). Evaluasi dampak jangka panjang kondisi tersebut terhadap kinerja jantung dan sistem organ lainnya adalah ....', 'none', '', '["Elastisitas arteri meningkat sehingga tekanan darah menurun drastis dan menyebabkan pembengkakan pada pembuluh vena kaki.", "Aliran darah menuju paru-paru terhenti sepenuhnya sehingga tubuh beralih menggunakan respirasi anaerob secara permanen.", "Lumen arteri menyempit sehingga suplai oksigen dan nutrisi ke otot jantung berkurang drastis, memicu nyeri dada (angina) hingga risiko serangan jantung (infark miokard).", "Jantung memompa darah lebih lambat untuk menghemat energi sehingga kadar oksigen di otak meningkat tajam."]'::jsonb, '[]'::jsonb, 'Aliran darah menuju paru-paru terhenti sepenuhnya sehingga tubuh beralih menggunakan respirasi anaerob secara permanen.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_38', 'PG', 'IPA SMP 8', 'Seorang pasien didiagnosis menderita peradangan hati (hepatitis) akut yang menyebabkan pembengkakan pada jaringan hati dan penyumbatan saluran empedu. Dokter menyarankan pasien tersebut untuk membatasi konsumsi makanan berlemak (seperti gorengan dan santan) selama masa pemulihan. Alasan ilmiah di balik saran medis tersebut adalah ....', 'none', '', '["gangguan sekresi cairan empedu ke usus halus menghambat proses emulsifikasi lemak sehingga lemak sulit dicerna oleh enzim lipase dan memicu mual serta diare berlemak", "hati tidak mampu memproduksi enzim pepsin dan tripsin sehingga lemak akan menumpuk dan merusak dinding lambung", "penyumbatan saluran empedu menyebabkan asam lambung naik ke kerongkongan setiap kali pasien mengonsumsi makanan berlemak", "jaringan hati yang meradang akan mengubah lemak menjadi zat racun amonia yang langsung merusak sel-sel saraf otak"]'::jsonb, '[]'::jsonb, 'hati tidak mampu memproduksi enzim pepsin dan tripsin sehingga lemak akan menumpuk dan merusak dinding lambung', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_39', 'PG', 'IPA SMP 8', 'Seorang ahli gizi melakukan uji kandungan nutrisi pada empat jenis bahan makanan (P, Q, R, dan S) untuk menyusun menu diet bagi pasien penderita diabetes melitus tipe 2 yang memerlukan asupan protein tinggi namun harus membatasi karbohidrat sederhana (gula). Berikut adalah hasil pengujiannya:<br><table style="border-collapse:collapse; width:100%; margin:8px 0; font-size:0.88rem;"><tr><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Bahan Makanan</th><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Uji Lugol (Amilum)</th><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Uji Benedict (Glukosa)</th><th style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Uji Biuret (Protein)</th></tr><tr><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">P</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Biru kehitaman</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Merah bata</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Biru muda</td></tr><tr><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Q</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Cokelat kekuningan</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Biru muda</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Ungu pekat</td></tr><tr><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">R</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Biru kehitaman</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Hijau kekuningan</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Ungu muda</td></tr><tr><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">S</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Cokelat kekuningan</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Merah bata</td><td style="border:1px solid #cbd5e1; padding:6px 8px; text-align:left;">Biru muda</td></tr></table><br>Berdasarkan data uji bahan makanan tersebut, pilihan bahan makanan yang paling tepat direkomendasikan sebagai sumber nutrisi utama pasien adalah ....', 'none', '', '["Bahan P, karena mengandung amilum dan glukosa tinggi sebagai sumber energi instan", "Bahan S, karena bebas dari amilum dan protein sehingga tidak membebani kerja ginjal", "Bahan R, karena mengandung kombinasi seimbang antara glukosa, amilum, dan sedikit protein", "Bahan Q, karena terbukti mengandung protein tinggi (uji Biuret ungu pekat) serta bebas dari amilum dan glukosa"]'::jsonb, '[]'::jsonb, 'Bahan S, karena bebas dari amilum dan protein sehingga tidak membebani kerja ginjal', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261101_08_40', 'PG', 'IPA SMP 8', 'Para atlet lari jarak jauh sering melakukan pemusatan latihan (<i>training camp</i>) di wilayah dataran tinggi (seperti Pangalengan atau Dieng) yang memiliki tekanan parsial oksigen lebih rendah dibandingkan dataran rendah. Setelah beberapa minggu berlatih di dataran tinggi, tubuh atlet mengalami aklimatisasi fisiologis yang meningkatkan performa mereka saat bertanding kembali di dataran rendah. Mekanisme adaptasi antara sistem pernapasan dan sistem peredaran darah yang terjadi pada atlet tersebut adalah ....', 'none', '', '["ukuran alveolus paru-paru membesar dua kali lipat sehingga atlet tidak perlu bernapas saat berlari cepat di dataran rendah", "hipoksia ringan merangsang ginjal memproduksi hormon eritropoietin yang memicu sumsum tulang meningkatkan produksi sel darah merah (eritrosit) dan hemoglobin sehingga kapasitas pengangkutan oksigen meningkat", "frekuensi denyut jantung menurun secara permanen sehingga darah mengalir lebih lambat dan oksigen lebih banyak diserap oleh jaringan otot", "pembuluh darah arteri berubah struktur menjadi lebih tipis seperti vena agar pertukaran oksigen dapat terjadi langsung di sepanjang pembuluh darah"]'::jsonb, '[]'::jsonb, 'hipoksia ringan merangsang ginjal memproduksi hormon eritropoietin yang memicu sumsum tulang meningkatkan produksi sel darah merah (eritrosit) dan hemoglobin sehingga kapasitas pengangkutan oksigen meningkat', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_01', 'PG', 'Informatika SMP 8', 'Dalam pengolahan data, tabel digunakan untuk ....', 'none', '', '["memperindah tampilan komputer", "mengorganisasi data agar mudah dibaca dan dianalisis", "menghapus data yang tidak diperlukan", "mengganti semua data menjadi gambar"]'::jsonb, '[]'::jsonb, 'mengorganisasi data agar mudah dibaca dan dianalisis', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_02', 'PG', 'Informatika SMP 8', 'Saat membuat tabel di Microsoft Excel, langkah yang tepat agar data dapat diubah menjadi tabel adalah ....', 'none', '', '["memblok seluruh data, kemudian menggunakan fitur Table", "menghapus seluruh data, kemudian membuat grafik", "mencetak data terlebih dahulu", "membuat grafik sebelum memasukkan data"]'::jsonb, '[]'::jsonb, 'memblok seluruh data, kemudian menggunakan fitur Table', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_03', 'PG', 'Informatika SMP 8', 'Pada fitur Table di Microsoft Excel, kolom bertipe angka seperti kolom Jumlah memiliki pilihan pengurutan ....', 'none', '', '["dari A ke Z", "hanya dari terkecil ke terbesar", "dari terkecil ke terbesar atau dari terbesar ke terkecil", "hanya berdasarkan warna sel"]'::jsonb, '[]'::jsonb, 'dari terkecil ke terbesar atau dari terbesar ke terkecil', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_04', 'PG', 'Informatika SMP 8', 'Fungsi tanda sama dengan (=) di awal rumus adalah ....', 'none', '', '["menghapus data yang telah dimasukkan pada lembar kerja", "memberi warna sel", "menandakan bahwa isi sel adalah perintah yang harus dihitung", "mengunci sel yang akan dihitung"]'::jsonb, '[]'::jsonb, 'menandakan bahwa isi sel adalah perintah yang harus dihitung', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_05', 'PG', 'Informatika SMP 8', 'Perhatikan data jumlah keaktifan murid kelas VII berikut!<br>Hasil rumus =SUM(C2:C5) adalah ....', 'image', './assets/soal/soal-0034.jpg', '["39", "46", "51", "58"]'::jsonb, '[]'::jsonb, '58', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_06', 'PG', 'Informatika SMP 8', 'Perhatikan data jumlah keaktifan murid kelas VII berikut!<br>Hasil rumus =COUNT(C2:C5) adalah ....', 'image', './assets/soal/soal-0034.jpg', '["1", "2", "3", "4"]'::jsonb, '[]'::jsonb, '4', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_07', 'PG', 'Informatika SMP 8', 'Perbedaan fungsi SUMIF dan SUMIFS adalah ....', 'none', '', '["SUMIF memiliki satu kondisi, sedangkan SUMIFS dapat memiliki lebih dari satu kondisi", "SUMIF memiliki lebih dari satu kondisi, sedangkan SUMIFS hanya memiliki satu kondisi", "SUMIF menghitung banyak data, sedangkan SUMIFS menjumlahkan data", "keduanya sama persis dan tidak ada perbedaan"]'::jsonb, '[]'::jsonb, 'SUMIF memiliki satu kondisi, sedangkan SUMIFS dapat memiliki lebih dari satu kondisi', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_08', 'PG', 'Informatika SMP 8', 'Perhatikan data jumlah keaktifan murid kelas VII berikut!<br>Hasil rumus =SUMIF(B2:B5;“Adhi”;C2:C5) adalah ....', 'image', './assets/soal/soal-0034.jpg', '["39", "46", "51", "58"]'::jsonb, '[]'::jsonb, '51', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_09', 'PG', 'Informatika SMP 8', 'Perhatikan data jumlah keaktifan murid kelas VII berikut!<br>Untuk mengetahui banyaknya data pada bulan Januari, rumus yang tepat adalah ....', 'image', './assets/soal/soal-0034.jpg', '["=SUMIF(B2:B5;“Adhi”;C2:C5)", "=SUMIF(B2:B5;“Januari”;C2:C5)", "=COUNT(B2:B5;“Januari”)", "=COUNTIF(A2:A5;“Januari”)"]'::jsonb, '[]'::jsonb, '=COUNTIF(A2:A5;“Januari”)', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_10', 'PG', 'Informatika SMP 8', 'Fungsi pencarian data pada lembar kerja terdiri atas dua kelompok, yaitu fungsi lookup dan fungsi ....', 'none', '', '["reference, seperti MATCH", "pivot table", "chart", "filter"]'::jsonb, '[]'::jsonb, 'reference, seperti MATCH', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_11', 'PG', 'Informatika SMP 8', 'Fungsi INDEX digunakan untuk ....', 'none', '', '["mencari posisi suatu data dalam grafik di Microsoft Excel", "mengambil isi sel berdasarkan nomor baris dan/atau kolom", "menghitung rata-rata", "menghapus data duplikat"]'::jsonb, '[]'::jsonb, 'mengambil isi sel berdasarkan nomor baris dan/atau kolom', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_12', 'PG', 'Informatika SMP 8', 'Perhatikan tabel berikut.<br>Jika terdapat data yang berbentuk seperti tabel di atas, rumus yang digunakan untuk pencarian data yang sesuai adalah ....', 'image', './assets/soal/soal-0035.jpg', '["VLOOKUP", "HLOOKUP", "MATCH", "INDEX"]'::jsonb, '[]'::jsonb, 'HLOOKUP', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_13', 'PG', 'Informatika SMP 8', 'Perhatikan rumus =VLOOKUP(A2;D1:F11;2;FALSE). Angka 2 pada rumus tersebut menunjukkan ....', 'none', '', '["kolom ke-2 dari table array yang hasilnya akan ditampilkan", "baris ke-2 dari table array yang hasilnya akan ditampilkan", "jumlah data yang dicari ada dua", "nilai yang dicari berada pada sel ke-2"]'::jsonb, '[]'::jsonb, 'kolom ke-2 dari table array yang hasilnya akan ditampilkan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_14', 'PG', 'Informatika SMP 8', 'Perhatikan tabel berikut.<br>Hasil dari =INDEX(C2:C6;3) adalah ....', 'image', './assets/soal/soal-0036.jpg', '["1500", "3000", "4000", "5000"]'::jsonb, '[]'::jsonb, '3000', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_15', 'PG', 'Informatika SMP 8', 'Perhatikan tabel berikut.<br>Hasil dari =MATCH(“K03”;A2:A6;0) adalah ....', 'image', './assets/soal/soal-0036.jpg', '["2", "3", "4", "#N/A"]'::jsonb, '[]'::jsonb, '3', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_16', 'PG', 'Informatika SMP 8', 'Rudi akan menyalin rumus VLOOKUP ke sepuluh sel di bawahnya. Agar range tabel pencarian tidak bergeser, Rudi harus ....', 'none', '', '["mengetik ulang rumus pada setiap sel", "memakai alamat absolut pada range tabel, misalnya $D$1:$F$11", "mengurutkan data dari terbesar ke terkecil", "mengganti FALSE dengan TRUE"]'::jsonb, '[]'::jsonb, 'memakai alamat absolut pada range tabel, misalnya $D$1:$F$11', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_17', 'PG', 'Informatika SMP 8', 'Perhatikan tabel berikut.<br>Rumus yang tepat untuk memilih nama barang urutan ke-3 pada data tersebut adalah ....', 'image', './assets/soal/soal-0036.jpg', '["=CHOOSE(3;B2;B3;B4;B5;B6)", "=CHOOSE(2;B2;B3;B4;B5;B6)", "=INDEX(3;B2;B3;B4;B5;B6)", "=INDEX(3;A2;A3;A4;A5;A6)"]'::jsonb, '[]'::jsonb, '=CHOOSE(3;B2;B3;B4;B5;B6)', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_18', 'PG', 'Informatika SMP 8', 'Perhatikan tabel berikut.<br>Jika kode barang yang dicari, yaitu B03, terdapat pada sel E2, rumus yang tepat untuk mencari Nama Barang adalah ....', 'image', './assets/soal/soal-0037.jpg', '["=VLOOKUP(E2;A2:C5;2;FALSE)", "=VLOOKUP(E2;A2:C5;3;FALSE)", "=HLOOKUP(E2;A2:C5;2;FALSE)", "=VLOOKUP(A2;E2:C5;2;FALSE)"]'::jsonb, '[]'::jsonb, '=VLOOKUP(E2;A2:C5;2;FALSE)', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_19', 'PG', 'Informatika SMP 8', 'Perhatikan tabel berikut.<br>Jika kode B03 yang akan dicari berada pada sel E2, rumus untuk mencari harga adalah ....', 'image', './assets/soal/soal-0035.jpg', '["=HLOOKUP(E2;A1:D3;2;FALSE)", "=HLOOKUP(E2;A1:D3;3;FALSE)", "=VLOOKUP(E2;A1:D3;3;FALSE)", "=VLOOKUP(E2;A1:D3;2;FALSE)"]'::jsonb, '[]'::jsonb, '=HLOOKUP(E2;A1:D3;3;FALSE)', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_20', 'PG', 'Informatika SMP 8', 'Rumus =VLOOKUP(“JAM”;D1:F11;2;FALSE) menghasilkan #N/A. Penyebab yang paling mungkin adalah ....', 'none', '', '["kode JAM tidak ditemukan pada kolom paling kiri tabel pencarian", "nomor kolom yang diminta bernilai 0", "fungsi VLOOKUP hanya dapat mencari angka", "tabel pencarian belum diberi warna"]'::jsonb, '[]'::jsonb, 'kode JAM tidak ditemukan pada kolom paling kiri tabel pencarian', 10, 'Sesuai kunci jawaban.')
INSERT INTO public.cbt_questions (id, type, subject, text, media_type, media_url, options, pairs, answer, weight, explanation) VALUES
  ('Q_20261104_08_21', 'PG', 'Informatika SMP 8', 'Jenis grafik yang menampilkan kontribusi setiap nilai terhadap keseluruhan dan hanya dapat dipakai untuk satu kelompok data adalah ....', 'none', '', '["grafik garis (line chart)", "grafik lingkaran (pie chart)", "grafik kolom (column chart)", "grafik batang (bar chart)"]'::jsonb, '[]'::jsonb, 'grafik lingkaran (pie chart)', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_22', 'PG', 'Informatika SMP 8', 'Perhatikan grafik berikut!<br>Grafik tersebut merupakan grafik kolom. Informasi yang dapat diketahui dari grafik tersebut adalah ....', 'none', '', '["perbandingan jumlah murid untuk setiap ekstrakurikuler", "jumlah keseluruhan murid yang mengikuti ekstrakurikuler", "tren perubahan data pada setiap ekstrakurikuler selama setahun", "jumlah murid yang mengikuti ekstrakurikuler futsal terhadap keseluruhan murid"]'::jsonb, '[]'::jsonb, 'perbandingan jumlah murid untuk setiap ekstrakurikuler', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261104_08_23', 'PG', 'Informatika SMP 8', 'Seorang siswa memiliki data nilai dan ingin membuat grafik untuk membandingkan nilai setiap siswa. Urutan pekerjaan yang paling tepat adalah ....', 'none', '', '["membuat grafik → memasukkan data → membuat tabel", "memasukkan dan menyusun data → membuat tabel → memilih data → membuat grafik", "membuat grafik → menggunakan VLOOKUP → memasukkan data", "menggunakan HLOOKUP → membuat grafik → memasukkan data"]'::jsonb, '[]'::jsonb, 'memasukkan dan menyusun data → membuat tabel → memilih data → membuat grafik', 10, 'Sesuai kunci jawaban.'),
